1	/*
2	  ONS Census 2021: population processing example
3	  Source data: RM121, Sex by age, England and Wales (ONS).
4	
5	  This program imports the accompanying CSV, assigns broad age bands,
6	  performs simple quality checks, and creates England-and-Wales totals and
7	  percentages by sex and age band.
8	
9	  In SAS Studio: upload both files to the same folder, then replace data_dir
10	  below with that folder's path.
11	*/
12	
13	%let data_dir=/Users/alex/Documents/Codex/2026-11-19/ca/outputs;
14	
15	filename onsin "&data_dir./ons_rm121_sex_by_age_2021.csv";
16	
17	/* Import explicitly so the program does not depend on PROC IMPORT guessing
18	   column types or variable names from the CSV headers. */
19	data ons_population;
20	    infile onsin dsd dlm=',' firstobs=2 lrecl=1048576 truncover;
21	    length la_code $9 la_name $80 sex $6 age_band $30 age_group $6;
22	    informat sex_code age_code population best32.;
23	    format population comma15.;
24	
25	    input la_code :$9.
26	          la_name :$80.
27	          sex_code :best32.
28	          sex :$6.
29	          age_code :best32.
30	          age_band :$30.
31	          population :best32.;
32	
33	    /* Convert the ONS 23 age categories into common reporting bands. */
34	    select (age_code);
35	        when (1, 2)                     age_group = '0-4';
36	        when (3, 4, 5, 6)               age_group = '5-15';
37	        when (7, 8, 9)                  age_group = '16-24';
38	        when (10, 11, 12, 13, 14, 15,
39	              16, 17)                   age_group = '25-64';
40	        when (18, 19, 20, 21, 22, 23)   age_group = '65+';
41	        otherwise                       age_group = 'Unknown';
42	    end;
43	
44	    if missing(la_code) or missing(sex) or missing(population) then delete;
45	run;
46	
47	/* Quality check: there should be no missing or negative counts. */
48	proc sql;
49	    title 'Data-quality check';
50	    select count(*) as records format=comma12.,
51	           sum(missing(age_group)) as missing_age_groups,
52	           sum(population < 0) as negative_counts
53	    from ons_population;
54	quit;
55	
56	/* Aggregate the local-authority records to England-and-Wales totals. */
57	proc summary data=ons_population nway;
58	    class sex age_group;
59	    var population;
60	    output out=population_by_age_sex(drop=_type_ _freq_) sum=population;
61	run;
62	
63	proc sql;
64	    create table population_results as
65	    select a.sex,
66	           a.age_group,
67	           a.population format=comma15. as population,
68	           100 * a.population / b.total_population
69	               as percent_of_sex format=5.1
70	    from population_by_age_sex as a
71	    inner join
72	      (select sex, sum(population) as total_population
73	       from population_by_age_sex
74	       group by sex) as b
75	    on a.sex = b.sex
76	    order by sex, a.age_group;
77	quit;
78	
79	title 'England and Wales population by sex and broad age group, Census 2021';
80	proc print data=population_results noobs label;
81	    label age_group='Age group'
82	          percent_of_sex='Percent within sex';
83	run;
84	
85	proc sgplot data=population_by_age_sex;
86	    vbar age_group / response=population group=sex groupdisplay=cluster;
87	    yaxis grid label='Population';
88	    xaxis label='Age group';
89	    title 'Population totals by sex and broad age group';
90	run;
91	
92	title;
