13	#' Read delimited text without guessing types, trimming values or discarding blanks.
14	#'
15	#' All fields remain character; malformed records carry their parser diagnostics.
16	read_population_text <- function(path, encoding = "UTF-8", delimiter = ",") {
17	  if (!file.exists(path)) stop(paste("Input does not exist:", path), call. = FALSE)
18	  data <- suppressWarnings(readr::read_delim(
19	    path, delim = delimiter, quote = '"', escape_double = TRUE,
20	    col_types = readr::cols(.default = readr::col_character()),
21	    locale = readr::locale(encoding = encoding), na = character(), trim_ws = FALSE,
22	    name_repair = "minimal", skip_empty_rows = FALSE,
23	    show_col_types = FALSE, progress = FALSE, lazy = FALSE
24	  ))
25	  parse_issues <- readr::problems(data)
26	  if (nrow(parse_issues)) {
27	    population_abort("Delimited-file parsing failed.", population_issue(
28	      "P0-04", paste0("Expected ", parse_issues$expected, "; actual ", parse_issues$actual),
29	      field = as.character(parse_issues$col)
30	    ), data)
31	  }
32	  data
33	}
