35	#' Import validated headers and preserve source field text.
36	#'
37	#' record_id is the logical data-record number, not necessarily the physical line.
38	ingest_population <- function(config) {
39	  raw <- read_population_text(config$input_file_path, config$encoding, config$delimiter)
40	  headers <- names(raw)
41	  expected <- unname(config$columns)
42	  if (anyDuplicated(headers) || !setequal(headers, expected)) {
43	    population_abort("Input headers do not match the configured schema.", population_issue(
44	      "P0-02", paste0("Missing: ", paste(setdiff(expected, headers), collapse = "; "),
45	                      ". Unexpected: ", paste(setdiff(headers, expected), collapse = "; "),
46	                      ". Duplicate headers: ", anyDuplicated(headers) > 0)
47	    ), raw)
48	  }
49	  canonical <- raw[unname(config$columns)]
50	  names(canonical) <- names(config$columns)
51	  canonical <- tibble::add_column(canonical, record_id = seq_len(nrow(canonical)), .before = 1)
52	  list(raw_data = raw, data = canonical)
53	}
