58	  sex <- read_population_text(config$sex_reference_path)
59	  expected_age <- c("source_age_code", "source_age_label", "age_group", "age_group_order")
60	  if (!setequal(names(age), expected_age) || anyDuplicated(names(age)) ||
61	      !setequal(names(sex), c("sex_code", "sex_label")) || anyDuplicated(names(sex))) {
62	    stop("Category reference headers are invalid.", call. = FALSE)
