66	      stop("Category references must be nonempty without missing fields.", call. = FALSE)
67	    }
68	  }
69	  if (anyDuplicated(age$source_age_code) || anyDuplicated(sex$sex_code) ||
70	      anyDuplicated(age$source_age_label) || anyDuplicated(sex$sex_label)) {
71	    stop("Category reference codes and labels must be unique.", call. = FALSE)
72	  }
73	  if (any(!grepl("^[1-9][0-9]*$", age$age_group_order))) {
74	    stop("Age-group order must contain positive integers.", call. = FALSE)
75	  }
