1	#' Resolve a project-relative path without depending on the working directory.
2	#'
3	#' Absolute paths and parent traversal are rejected to keep configuration portable.
4	population_path <- function(project_root, relative_path) {
5	  if (!is.character(relative_path) || length(relative_path) != 1L ||
6	      is.na(relative_path) || !nzchar(relative_path) ||
7	      grepl("^(~|/|[A-Za-z]:)|(^|[/\\\\])\\.\\.([/\\\\]|$)", relative_path)) {
8	    stop("Paths must be nonempty project-relative paths without '..'.", call. = FALSE)
9	  }
10	  root <- normalizePath(project_root, mustWork = TRUE)
11	  path <- normalizePath(file.path(root, relative_path), mustWork = FALSE)
12	  if (!startsWith(path, paste0(root, .Platform$file.sep))) {
13	    stop("Configured path escapes the project root.", call. = FALSE)
14	  }
15	  path
16	}
17	
18	#' Load a source contract; unknown provenance remains unknown.
19	#'
20	#' Returns configuration with resolved paths. Does not create output directories.
21	read_population_config <- function(project_root, config_file) {
22	  config_path <- population_path(project_root, config_file)
23	  if (!file.exists(config_path)) stop("Configuration file does not exist.", call. = FALSE)
24	  config <- yaml::read_yaml(config_path, eval.expr = FALSE)
25	  required <- c("dataset_id", "input_file", "output_directory", "encoding", "delimiter",
26	                "age_reference", "sex_reference", "columns", "context", "analysis", "acceptance")
27	  if (!is.list(config) || !all(required %in% names(config))) {
28	    stop("Configuration is missing required settings.", call. = FALSE)
29	  }
30	  for (field in c("dataset_id", "encoding", "delimiter")) {
31	    if (!is.character(config[[field]]) || length(config[[field]]) != 1L ||
32	        is.na(config[[field]]) || !nzchar(config[[field]])) {
33	      stop(paste("Invalid configuration setting:", field), call. = FALSE)
34	    }
35	  }
36	  if (!grepl("^[A-Za-z0-9_-]+$", config$dataset_id) || nchar(config$delimiter) != 1L) {
37	    stop("Invalid dataset identifier or delimiter.", call. = FALSE)
38	  }
39	  expected <- c("geography_code", "geography_name", "sex_code", "sex_label",
40	                "source_age_code", "source_age_label", "population_raw")
41	  columns <- unlist(config$columns, use.names = TRUE)
42	  if (!identical(sort(names(columns)), sort(expected)) || !is.character(columns) ||
43	      anyNA(columns) || any(!nzchar(trimws(columns))) || anyDuplicated(columns)) {
44	    stop("Column mapping must define the seven unique canonical fields.", call. = FALSE)
45	  }
46	  if (!isTRUE(config$analysis$complete_category_grid) ||
47	      !identical(config$analysis$percentage_denominator, "within_sex")) {
48	    stop("This implementation requires a complete grid and within-sex percentages.", call. = FALSE)
49	  }
50	  config$columns <- columns
51	  config$project_root <- normalizePath(project_root, mustWork = TRUE)
52	  config$config_path <- config_path
53	  for (field in c("input_file", "output_directory", "age_reference", "sex_reference")) {
54	    config[[paste0(field, "_path")]] <- population_path(project_root, config[[field]])
55	  }
56	  for (field in c("input_file_path", "age_reference_path", "sex_reference_path")) {
57	    if (!file.exists(config[[field]]) || dir.exists(config[[field]])) {
58	      stop(paste("Required file does not exist:", config[[field]]), call. = FALSE)
59	    }
60	  }
61	  input_directory <- dirname(config$input_file_path)
62	  if (identical(config$output_directory_path, input_directory) ||
63	      startsWith(config$output_directory_path, paste0(input_directory, .Platform$file.sep))) {
64	    stop("Outputs must not be written into the source-data directory.", call. = FALSE)
65	  }
66	  config
67	}
