14	#' Aggregate a validated single-release dataset using explicit grouping keys.
15	#'
16	#' observation_keys describe the full source grain. Future period-aware adapters
17	#' must include period in both the observation keys and retained grouping keys.
18	aggregate_population <- function(data, group_keys, observation_keys) {
19	  required <- unique(c(group_keys, observation_keys, "population"))
20	  if (!length(group_keys) || !length(observation_keys) ||
21	      !all(required %in% names(data)) || "population" %in% c(group_keys, observation_keys) ||
22	      anyDuplicated(group_keys) || anyDuplicated(observation_keys) || !nrow(data)) {
23	    stop("Aggregation requires explicit valid keys and nonempty data.", call. = FALSE)
24	  }
25	  if (anyNA(data[unique(c(group_keys, observation_keys))]) ||
26	      anyDuplicated(data[observation_keys])) {
27	    stop("Source observation keys must be nonmissing and unique.", call. = FALSE)
28	  }
29	  # Known context dimensions may never be silently pooled across their values.
30	  context_keys <- intersect(c("period", "release_id", "geography_version", "measure",
31	                              "sex_classification", "age_classification"), names(data))
32	  for (key in setdiff(context_keys, group_keys)) {
